+      u_coord = u_size - U(1.0);
+      grad_clip = U(0.0);
+    }
+    u_grad_in = u_grad_in * grad_refl * grad_clip;
+  }
+
+  coord = static_cast<T>(u_coord);
+  *grad_in = static_cast<T>(u_grad_in);
