+template <typename T>
+T grid_sampler_compute_source_index_set_grad(
+    T coord,
+    int32_t size,
+    int32_t padding_mode,
+    bool align_corners,
+    thread T* grad_in) {
+  using U = opmath_t<T>;
+  U u_coord = static_cast<U>(coord);
+  U u_grad_in = static_cast<U>(*grad_in);
+  U u_size = static_cast<U>(size);
