+    }
+
+    // Clip after reflection
+    U grad_clip = U(1.0);
+    if (u_coord < U(0.0)) {
+      u_coord = U(0.0);
+      grad_clip = U(0.0);
+    } else if (u_coord > u_size - U(1.0)) {
