+  size_t operator()(const CuSparseLtPlanCacheKey& k) const {
+    return c10::get_hash(
+        k.m, k.k, k.n,
+        k.input_type, k.output_type, k.C_type,
+        k.compute_type,
+        k.transpose_result, k.is_B_contiguous,
