+  do {                                                                  \
+    hipdnnStatus_t status = EXPR;                                       \
+    if (status != HIPDNN_STATUS_SUCCESS) {                              \
+      if (status == HIPDNN_STATUS_NOT_SUPPORTED) {                      \
