+            ##__VA_ARGS__);                                             \
+      } else {                                                          \
+        TORCH_CHECK_WITH(                                               \
+            HipDNNError,                                                \
+            false,                                                      \
+            "hipDNN error: ",                                           \
+            hipdnnGetErrorString(status),                               \
+            ##__VA_ARGS__);                                             \
+      }                                                                 \
+    }                                                                   \
+  } while (0)
+
+#define HIPDNN_FE_CHECK(EXPR)          \
