+      return hipdnn_frontend::DataType::FLOAT;
+    case at::kHalf:
+      return hipdnn_frontend::DataType::HALF;
+    case at::kBFloat16:
+      return hipdnn_frontend::DataType::BFLOAT16;
+    default:
+      TORCH_CHECK(
+          false,
+          "getHipdnnDataType() not supported for ",
+          toString(tensor.scalar_type()));
+  }
+}
